+// Full 64x64->128 product: returns the high half, stores the low half.
+#if defined(__GNUC__) && defined(__x86_64__)
+// A single mulq: GCC otherwise tends to move the 128-bit product through the
+// stack in tight loops. b goes to rax: it is typically a value loaded just
+// for this, while a is often still needed afterwards.
+static inline uint64_t binary_fuse_mulhilo(uint64_t a, uint64_t b, uint64_t *lo) {
+  uint64_t l, h;
+  __asm__("mulq %3" : "=a"(l), "=d"(h) : "a"(b), "rm"(a) : "cc");
+  *lo = l;
+  return h;
+}
+#elif defined(__SIZEOF_INT128__)  // compilers supporting __uint128, e.g., gcc, clang
+static inline uint64_t binary_fuse_mulhilo(uint64_t a, uint64_t b, uint64_t *lo) {
+  __uint128_t p = (__uint128_t)a * b;
+  *lo = (uint64_t)p;
+  return (uint64_t)(p >> 64U);
+}
+#else  // portable implementation using uint64_t
+static inline uint64_t binary_fuse_mulhilo(uint64_t a, uint64_t b, uint64_t *lo) {
+  const uint64_t a0 = (uint32_t) a;
+  const uint64_t a1 = a >> 32;
+  const uint64_t b0 = (uint32_t) b;
+  const uint64_t b1 = b >> 32;
+  const uint64_t p11 = a1 * b1;
+  const uint64_t p01 = a0 * b1;
+  const uint64_t p10 = a1 * b0;
+  const uint64_t p00 = a0 * b0;
+  // 64-bit product + two 32-bit values cannot overflow
+  const uint64_t middle = p10 + (p00 >> 32) + (uint32_t) p01;
+  *lo = (middle << 32) | (uint32_t) p00;
+  return p11 + (middle >> 32) + (p01 >> 32);
+}
+#endif
