+static inline uint64_t binary_fuse_mulhi(uint64_t a, uint64_t b) {
+  uint64_t h = (uint64_t)(((__uint128_t)a * b) >> 64U);
+#if defined(__GNUC__)
+  // keeps GCC from moving the high half through the stack in tight loops
+  __asm__("" : "+r"(h));
+#endif
+  return h;
