+/**
+ * Layout. A key with hash h has three locations, one in each of three
+ * consecutive segments:
+ *   h0 = mulhi(h, SegmentCountLength)
+ *   h1 = (h0 + SegmentLength) ^ ((h >> 18) & (SegmentLength - 1))
+ *   h2 = (h0 + 2 * SegmentLength) ^ (h & (SegmentLength - 1))
